	@Test
	void missingBatchSizeIgnoresLegacyPageSizeAndTotalCookies() throws Exception {
		StringBuilder text = new StringBuilder("SELECT ?n WHERE { VALUES ?n {");
		for (int index = 0; index < 150; index++) {
			text.append(' ').append(index);
		}
		text.append(" } } ORDER BY ?n");
		MockHttpServletRequest request = rawRequest(Map.of());
		request.setCookies(new Cookie("limit_query", "100"), new Cookie("know_total", "150"),
				new Cookie("total_result_count", "150"));

		List<JsonNode> records = evaluate(text.toString(), request);

		assertThat(rows(records)).hasSize(150);
		assertThat(end(records).path("result-limit").asInt()).isEqualTo(1_000_000);
		assertThat(end(records).path("result-batch-count").asInt()).isEqualTo(150);
		assertThat(end(records).path("result-has-more").asBoolean()).isFalse();
		assertThat(end(records).path("total-result-count").asInt()).isEqualTo(150);
	}

