	@ParameterizedTest
	@MethodSource("slicedSelectQueries")
	void resultWindowsPreserveUserSlicesAndReportTheExactFullCount(String text) throws Exception {
		List<JsonNode> first = evaluate(text, rawRequest(Map.of("batch-size", "2")));
		List<JsonNode> second = evaluate(text, rawRequest(Map.of("batch-size", "2", "batch-offset", "2")));
		List<JsonNode> last = evaluate(text, rawRequest(Map.of("batch-size", "2", "batch-offset", "4")));

		assertThat(numbers(first)).containsExactly("1", "2");
		assertThat(numbers(second)).containsExactly("3", "4");
		assertThat(numbers(last)).containsExactly("5");
		assertThat(end(first).path("result-has-more").asBoolean()).isTrue();
		assertThat(end(second).path("result-has-more").asBoolean()).isTrue();
		assertThat(end(last).path("result-has-more").asBoolean()).isFalse();
		assertThat(end(last).path("result-batch-count").asInt()).isEqualTo(1);
		assertCompleted(end(first), 5);
		assertCompleted(end(second), 5);
		assertCompleted(end(last), 5);
		assertThat(metadata(second).path("query-text").asText()).isEqualTo(text);
	}

