	private static List<JsonNode> evaluate(String query, MockHttpServletRequest request) throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			return evaluate(connection, query, request);
		} finally {
			repository.shutDown();
		}
	}

	private static List<JsonNode> evaluate(RepositoryConnection connection, String query,
			MockHttpServletRequest request) throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		WorkbenchPageResultWriter writer = new WorkbenchPageResultWriter(output);
		TupleResultBuilder builder = new TupleResultBuilder(writer, SimpleValueFactory.getInstance());
		QueryEvaluator.INSTANCE.extractQueryAndEvaluate(builder, mock(HttpServletResponse.class), output, connection,
				query, new WorkbenchRequest(null, request, Map.of("queryLn", "SPARQL", "limit_query", "100")),
				mock(CookieHandler.class), query);
		return output.toString(StandardCharsets.UTF_8).lines().map(JSON::readTree).toList();
	}

	private static MockHttpServletRequest rawRequest(Map<String, String> parameters) {
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/query");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		parameters.forEach(request::addParameter);
		return request;
	}

	private static List<JsonNode> rows(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.flatMap(record -> record.path("values").valueStream())
				.toList();
	}

	private static List<String> numbers(List<JsonNode> records) {
		return rows(records).stream().map(row -> row.get(0).path("value").asText()).toList();
	}

	private static JsonNode end(List<JsonNode> records) {
		JsonNode terminal = records.get(records.size() - 1);
		assertThat(terminal.path("type").asText()).isEqualTo("end");
		return terminal.path("metadata");
	}

	private static void assertCompleted(JsonNode terminal, long exactTotal) {
		assertThat(terminal.path("total-result-count").asLong()).isEqualTo(exactTotal);
		assertThat(terminal.path("query-elapsed-ms").asLong()).isGreaterThanOrEqualTo(0);
		assertThat(terminal.path("query-result-status").asText()).isEqualTo("completed");
	}

	private static JsonNode metadata(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.findFirst()
				.orElseThrow()
				.path("values");
	}

	/** Retains one flushed protocol record, rather than materializing the million-row response in the test. */
	private static final class CountingPageOutputStream extends OutputStream {
		private final ByteArrayOutputStream record = new ByteArrayOutputStream();
		private long rows;
		private JsonNode terminal;

		@Override
		public void write(int value) {
			record.write(value);
		}

		@Override
		public void write(byte[] bytes, int offset, int length) {
			record.write(bytes, offset, length);
		}

		@Override
		public void flush() {
			for (String line : record.toString(StandardCharsets.UTF_8).lines().toList()) {
				JsonNode value = JSON.readTree(line);
				if ("rows".equals(value.path("type").asText())) {
					rows += value.path("values").size();
				} else if ("end".equals(value.path("type").asText())) {
					terminal = value.path("metadata");
				}
			}
			record.reset();
		}
	}
